compile.workshop:
variables {
    global:
        0: g
}

rule ("canonical and renamed member spellings") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, Hero(Soldier: 76));
        Set Global Variable(g, Hero(Cassidy));
        Set Global Variable(g, Map(Route 66));
        Set Global Variable(g, Team 2);
        Set Global Variable(g, Do Not Clip);
        Set Global Variable(g, Clip Against Surfaces);
    }
}

